  ('snake_plant', 'Snake Plant', 'Dracaena trifasciata', 'assets/images/snake.png', 14, 30, 21, 'Let the growing medium dry substantially before watering.', 'Bright daylight', 'Place near a window with good daylight. Some direct sun is fine; introduce stronger sun gradually.', 'https://plants.ces.ncsu.edu/plants/dracaena-trifasciata/', 1, 1, 'reviewed'),
  ('monstera', 'Monstera', 'Monstera deliciosa', 'assets/images/monstera.png', 7, 14, 10, 'Check the top 1–2 inches of soil and avoid waterlogging.', 'Indirect daylight', 'Place near a bright window, away from strong sun shining directly on the leaves.', 'https://plants.ces.ncsu.edu/plants/monstera-deliciosa/', 1, 1, 'reviewed'),
  ('rubber_plant', 'Rubber Plant', 'Ficus elastica', 'assets/images/rubber.png', 7, 21, 14, 'Use a free-draining medium and check before watering.', 'Bright, indirect light', 'Place near a bright window, sheltered from strong afternoon sun. Daylight should reach the plant without harsh sun on its leaves.', 'https://plants.ces.ncsu.edu/plants/ficus-elastica/', 1, 1, 'reviewed'),
  ('pothos', 'Pothos', 'Epipremnum aureum', 'assets/images/pothos.jpg', 7, 21, 14, 'Allow the soil to dry between checks; avoid keeping it constantly wet.', 'Bright, indirect light', 'Choose a bright spot out of strong direct sun. It tolerates lower light, but grows best with plenty of indirect daylight.', 'https://plants.ces.ncsu.edu/plants/epipremnum-aureum/', 1, 1, 'reviewed'),
  ('spider_plant', 'Spider Plant', 'Chlorophytum comosum', 'assets/images/spider.jpg', 7, 14, 10, 'Keep the soil lightly moist, but let excess water drain away.', 'Medium, indirect daylight', 'Place in medium indirect light. Avoid strong direct sun; it tolerates lower light and short dry periods.', 'https://plants.ces.ncsu.edu/plants/chlorophytum-comosum/', 1, 1, 'reviewed'),
